(async()=>{'use strict';
const root=new URL('/ordine/',location.origin),$=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='gin-order-demo-v2', stations={calda:'Cucina calda',frittura:'Frittura',sushi:'Sushi',maki:'Maki',bar:'BAR'}, params=new URLSearchParams(location.search);let view=document.body.dataset.view||'cliente',station=params.get('station')||'calda',table=Number(params.get('table'))||Number(params.get('tavolo'))||5,cat='Tutti',query='',cart={},notes={},notice='',round=1,quantityDialog=null,salaDialog=null,activeRoom='sala1',movingTables=false,suppressTableClick=false;
const initial=()=>({menu:GIN_MENU.map(d=>({...d,station:['Tempura','Antipasti'].includes(d.category)?'frittura':['Nigiri','Insalata & Poke'].includes(d.category)?'sushi':['Riso','Spaghetti','Piatti caldi'].includes(d.category)?'calda':'maki',limit:0,instructions:'',available:true,meal:'entrambi'})),tables:{},orders:[]});
let state;let storageOK=true;
const assigned=d=>Array.isArray(d.stations)&&d.stations.length?d.stations:[d.station].filter(s=>stations[s]);
const owner=d=>assigned(d).includes(d.completionStation)?d.completionStation:assigned(d)[0];
const instruction=(d,s)=>d.stationInstructions?.[s]??d.instructions??'';
function normalize(){state.orders.forEach(o=>o.items.forEach(i=>{if(!Number.isInteger(i.readyQty))i.readyQty=['ready','served'].includes(i.status)?i.qty:0;if(!Number.isInteger(i.servedQty))i.servedQty=i.status==='served'?i.qty:0;i.readyQty=Math.max(0,Math.min(i.qty,i.readyQty));i.servedQty=Math.max(0,Math.min(i.readyQty,i.servedQty));syncStatus(i)}))}
function syncStatus(i){i.status=i.servedQty===i.qty?'served':i.readyQty===i.qty?'ready':i.readyQty>0||i.status==='working'?'working':'new'}
function amount(i,kind){return kind==='complete'?i.qty-i.readyQty:kind==='serve'?i.readyQty-i.servedQty:i.servedQty}
function findItem(ref){const o=state.orders.find(o=>o.id===ref.order);return {o,i:o?.items.find(i=>i.id===ref.item)}}
function groupItems(kind){const groups=new Map();state.orders.forEach(o=>o.items.forEach(i=>{const q=amount(i,kind);if(!q||(kind==='complete'&&!assigned(i).includes(station)))return;const text=kind==='complete'?instruction(i,station):'';const key=JSON.stringify([i.dish,i.name,i.note,text,kind==='complete'?owner(i):'']);if(!groups.has(key))groups.set(key,{name:i.name,dish:i.dish,note:i.note,instructions:text,image:i.image||state.menu.find(d=>d.id===i.dish)?.image,rows:new Map(),total:0,time:o.time});const g=groups.get(key);g.total+=q;g.time=Math.min(g.time,o.time);const rowkey=JSON.stringify([o.table,o.session,o.round,i.status==='new'?'new':'started']);if(!g.rows.has(rowkey))g.rows.set(rowkey,{table:o.table,round:o.round,time:o.time,qty:0,refs:[],canComplete:owner(i)===station,owner:owner(i)});const row=g.rows.get(rowkey);row.qty+=q;row.refs.push({order:o.id,item:i.id})}));return [...groups.values()].sort((a,b)=>a.time-b.time)}
function choiceTiles(name,options,value,label){return `<fieldset class="choice-field"><legend>${esc(label)}</legend><div class="choice-grid">${options.map(([v,t])=>`<label class="choice-square"><input type="radio" name="${esc(name)}" value="${esc(v)}" ${String(v)===String(value)?'checked':''} required><span>${esc(t)}</span></label>`).join('')}</div></fieldset>`}
function numberStepper(name,value,min,max,label){return `<fieldset class="choice-field"><legend>${esc(label)}</legend><div class="number-stepper" data-min="${min}" data-max="${max}"><input type="hidden" name="${name}" value="${value}">${btn('−','step',`data-delta="-1" aria-label="Riduci ${esc(label)}"`)}<output aria-live="polite">${name==='limit'&&Number(value)===0?'∞':value}</output>${btn('+','step',`data-delta="1" aria-label="Aumenta ${esc(label)}"`)}</div></fieldset>`}
function quantityMarkup(){if(!quantityDialog)return '';const d=quantityDialog,limit=d.refs.reduce((n,ref)=>{const {i}=findItem(ref);return n+(i?amount(i,d.kind):0)},0);return `<div class="quantity-overlay"><section class="panel quantity-panel" role="dialog" aria-modal="true" aria-labelledby="quantity-title"><h2 id="quantity-title">${({complete:'Completa preparazione',serve:'Segna come servito',undo:'Annulla servizio'})[d.kind]}</h2><p>${esc(d.name)} · Tavolo ${d.table}</p><form data-quantity="true">${choiceTiles('quantity',Array.from({length:limit},(_,i)=>[i+1,i+1]),limit,'Porzioni')}<p>${limit} porzioni disponibili</p><div class="actions">${btn('Annulla','dismiss')}<button type="submit">Conferma</button></div></form></section></div>`}
function tableTile(row,g,kind){const clickable=kind!=='complete'||row.canComplete;const attrs=`data-action="quantity" data-kind="${kind}" data-name="${esc(g.name)}" data-table="${row.table}" data-refs="${esc(JSON.stringify(row.refs))}"`;return `<${clickable?'button':'div'} class="tile table-tile ${clickable?'':'prep-only'}" ${clickable?attrs:''}><b>T${String(row.table).padStart(2,'0')} <strong>×${row.qty}</strong></b><small>Giro ${row.round} · ${Math.max(0,Math.floor((Date.now()-row.time)/60000))} min</small><span>${kind==='complete'?(clickable?'Tocca per completare':'Solo preparazione · completa '+stations[row.owner]):kind==='serve'?'Servito ✓':'Annulla servizio ↶'}</span></${clickable?'button':'div'}>`}

const LIVE=true;
let adminTab='overview';
let ME=null,ROLE='anonymous',AVAILABLE=[],BUSINESS_DATE='',baseState=null,uncertainWrite=null,saving=false,online=true,REPORT=null;
const API_VIEW=document.body.dataset.view||'cliente';
const LIVE_PARAMS=new URLSearchParams(location.search);
function apiURL(path='/api/bootstrap'){const u=new URL(path,location.origin);u.searchParams.set('view',API_VIEW);for(const k of ['table','key','station'])if(LIVE_PARAMS.has(k))u.searchParams.set(k,LIVE_PARAMS.get(k));return u;}
function applyRemote(data){state=data.state;ME=data.me;ROLE=data.role;AVAILABLE=data.availableMeals||[];BUSINESS_DATE=data.businessDate||new Date(data.serverTime).toISOString().slice(0,10);baseState=structuredClone(state);normalize();}
async function initializeLive(){try{const r=await fetch(apiURL(),{cache:'no-store'}),data=await r.json();if(!r.ok)throw Object.assign(new Error(data.error),{status:r.status});applyRemote(data);if(ROLE==='kitchen'&&!ME.stations.includes(station)){station=ME.stations[0];LIVE_PARAMS.set('station',station);}return true;}catch(e){const ret=encodeURIComponent(location.pathname+location.search);document.body.innerHTML=`<main class="login-screen"><h1>GIN SUSHI</h1><p>${esc(e.message)}</p>${API_VIEW==='cliente'||API_VIEW==='storico'?'<p>Scansiona il codice del tuo tavolo. Il personale deve prima aprirlo.</p>':`<a class="pill" target="_top" href="/signin-with-chatgpt?return_to=${ret}">Accedi con ChatGPT</a><p>Ogni dipendente usa il proprio account. L’amministratore abilita email e ruolo.</p>`}<p><a href="/">Portali GIN SUSHI</a></p></main>`;return false;}}
async function syncLive(force=false){if(saving)return;if(uncertainWrite){await recoverWrite();return;}try{const r=await fetch(apiURL(),{cache:'no-store'}),data=await r.json();if(!r.ok){if(r.status===403){location.reload();return;}throw Error(data.error);}online=true;const status=document.querySelector('.connection-status');if(status)status.hidden=true;const changed=JSON.stringify(data.state)!==JSON.stringify(baseState);applyRemote(data);if(force||(changed&&view!=='admin'&&!salaDialog&&!quantityDialog&&!document.activeElement?.closest('form')&&!document.activeElement?.matches('input,textarea')))render();}catch(e){online=false;const el=document.querySelector('.connection-status');if(el){el.hidden=false;el.textContent='Connessione assente · riprova prima di inviare';el.classList.add('offline');}}}
async function save(){if(saving||uncertainWrite){notice='Attendi la conferma del salvataggio precedente.';return false;}const write={requestId:crypto.randomUUID(),base:baseState,next:structuredClone(state)};uncertainWrite=write;saving=true;try{const r=await fetch(apiURL('/api/mutate'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(write)}),data=await r.json();if(!r.ok){uncertainWrite=null;throw Error(data.error||'Operazione non salvata');}applyRemote(data);uncertainWrite=null;online=true;return true;}catch(e){notice=uncertainWrite?'Connessione interrotta. Verifico lo stesso invio: non reinviare.':e.message;setTimeout(()=>syncLive(true),100);return false;}finally{saving=false;}}
async function recoverWrite(){if(!uncertainWrite||saving)return;saving=true;const write=uncertainWrite;try{const r=await fetch(apiURL('/api/mutate'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(write)}),data=await r.json();if(!r.ok){uncertainWrite=null;notice=data.error||'Operazione non salvata';setTimeout(()=>syncLive(true),50);return;}const wasOrder=ROLE==='guest'&&(write.next.orders||[]).some(o=>!(write.base.orders||[]).some(b=>b.id===o.id));applyRemote(data);uncertainWrite=null;online=true;notice='Salvataggio confermato dal ristorante.';if(wasOrder){cart={};notes={};view='storico';}render();}catch(e){online=false;}finally{saving=false;}}

function roleLinks(){const list=ROLE==='admin'?[['sala/','Servizio'],['cucina/','Cucina'],['uscita/','Uscita'],['cassa/','Cassa'],['admin/','Admin']]:ROLE==='waiter'?[['sala/','Servizio']]:ROLE==='kitchen'?[['cucina/?station='+(ME.stations[0]||'calda'),'Cucina']]:ROLE==='pass'?[['uscita/','Uscita']]:ROLE==='cashier'?[['cassa/','Cassa']]:[];return list.map(([p,n])=>nav(p,n)).join('');}
function serviceStatus(){const m=AVAILABLE.map(x=>({pranzo:'Pranzo',cena:'Cena',carta:'À la carte'})[x]).join(' / ');return state.service.enabled?(m||'Fuori orario di servizio'):'Servizio da attivare in Admin';}
function chooseMealMarkup(){return `<section class="panel meal-selection"><h2>Scegli il tuo menu</h2><p>${esc(serviceStatus())}</p><div class="meal-tiles">${[['pranzo','Pranzo'],['cena','Cena'],['carta','À la carte']].map(([id,label])=>btn(label,'guest-meal',`data-meal="${id}" ${!AVAILABLE.includes(id)?'disabled':''}`)).join('')}</div><p>La disponibilità segue gli orari del ristorante (Europe/Rome).</p></section>`;}
async function chooseGuestMeal(meal){if(!AVAILABLE.includes(meal)){notice='Menu non disponibile in questo orario.';render();return;}const t=state.tables[table],before=cloneFront(state);if(!t?.open)return;t.meal=meal;t.rates=meal==='carta'?{...currentRates('carta')}:currentRates(meal);if(!await save())state=before;render();}
const cloneFront=x=>structuredClone(x);
function serviceTableDialog(){if(!salaDialog)return '';ensureSala();const d=salaDialog;if(d.kind==='room'||d.kind==='newtable'||d.kind==='move')return legacySalaDialogMarkup();const n=d.table,t=state.tables[n];if(!n)return '';return `<div class="quantity-overlay"><section class="panel sala-dialog" role="dialog" aria-label="Gestione tavolo"><div class="title"><h2>Tavolo ${n}</h2>${btn('✕','sala-dismiss','aria-label="Chiudi pannello"')}</div><p>${t?.open?'Tavolo attivo':'Attiva il tavolo per consentire gli ordini dal codice QR.'}</p><p>Cameriere: <b>${esc(t?.waiterName||ME?.name||'')}</b></p><form ${t?.open?`data-attendance="${n}"`:`data-open="${n}"`}>${numberStepper('adults',t?.open?t.adults:2,0,99,'Adulti')}${numberStepper('children',t?.open?t.children:0,0,99,'Bambini')}<div class="actions"><button>${t?.open?'Salva persone':'Apri tavolo'}</button></div></form></section></div>`;}
function billForTable(n){const t=state.tables[n];if(!t?.meal)return null;const bill=billFor(t.adults,t.children,t.rates);if(!bill)return null;if(t.meal==='carta'){bill.lines=bill.lines.filter(l=>!l.name.startsWith('Menu'));for(const o of state.orders.filter(o=>o.table===n&&o.session===t.session))for(const i of o.items)bill.lines.unshift({name:i.name,qty:i.qty,unit:i.unitCents||0});}else {for(const o of state.orders.filter(o=>o.table===n&&o.session===t.session))for(const i of o.items)if(i.unitCents>0)bill.lines.push({name:i.name,qty:i.qty,unit:i.unitCents});}bill.total=bill.lines.reduce((a,l)=>a+l.qty*l.unit,0);return bill;}
function cashDialogMarkup(){if(!salaDialog)return '';if(['room','newtable','move'].includes(salaDialog.kind))return legacySalaDialogMarkup();const n=salaDialog.table,t=state.tables[n];if(!t?.open)return '';const bill=billForTable(n),pending=pendingTable(n);return `<div class="quantity-overlay"><section class="panel sala-dialog" role="dialog" aria-label="Conto tavolo"><div class="title"><h2>Conto · Tavolo ${n}</h2>${btn('✕','sala-dismiss','aria-label="Chiudi pannello"')}</div><p>${t.adults} adulti · ${t.children} bambini · ${esc(t.meal||'Menu non ancora scelto')}</p><p>Cameriere: ${esc(t.waiterName||'')}</p>${bill?billMarkup(bill):'<div class="notice">Il cliente deve scegliere il menu dal codice QR prima del conto.</div>'}<form data-settle="${n}">${choiceTiles('payment',[['contanti','Contanti'],['carta','Carta / POS esterno'],['bonifico','Bonifico']],'contanti','Pagamento registrato')}${pending?`<p>${pending} porzioni ancora da servire.</p>`:''}<button ${!bill||pending?'disabled':''}>Registra pagamento e chiudi tavolo</button></form><p class="muted">Registra un pagamento già ricevuto. Il terminale POS e il documento fiscale restano esterni.</p></section></div>`;}
function cassa(){ensureSala();shell(`<div class="title"><div><small>CASSA</small><h1>Tavoli e conti</h1></div></div>${floorPlan(true)}<h2>Pagamenti di oggi</h2><div class="panel">${state.receipts.map(r=>`<div class="bill-line"><span>T${r.table} · ${esc(r.payment)}<small>${esc(r.cashier||'')} · ${r.adults} adulti, ${r.children} bambini</small></span><b>${euros(r.total)}</b></div>`).join('')||'Nessun conto chiuso.'}</div>`);}

async function settleForm(n,payment){const t=state.tables[n],calculation=billForTable(n);if(!t?.open||!calculation||pendingTable(n))return;const before=cloneFront(state);state.receipts.push({...calculation,id:crypto.randomUUID(),table:n,session:t.session,meal:t.meal,time:Date.now(),payment});t.open=false;t.lastBill=calculation;if(!await save())state=before;else {notice='Pagamento registrato · Tavolo '+n+' chiuso.';salaDialog=null;}render();}
function stationEditor(d){const selected=assigned(d);return `<fieldset class="wide station-config compact-stations"><legend>Postazioni</legend><div class="station-ticks">${Object.entries(stations).map(([st,label])=>`<label class="station-tick"><input type="checkbox" name="stations" value="${st}" ${selected.includes(st)?'checked':''}> ${label}</label>`).join('')}</div>${Object.entries(stations).map(([st,label])=>`<div class="station-detail" data-detail="${st}" ${selected.includes(st)?'':'hidden'}><label class="station-owner"><input type="radio" name="completionStation" value="${st}" ${owner(d)===st?'checked':''} ${selected.includes(st)?'':'disabled'}> ${label} · conferma piatto pronto</label><label>Preparazione per ${label}<textarea name="instructions_${st}" maxlength="500">${esc(instruction(d,st))}</textarea></label></div>`).join('')}</fieldset>`;}
function staffMarkup(){return `<section class="panel"><h2>Account dipendenti</h2><p>Ogni persona accede con il proprio account ChatGPT. Inserisci la stessa email e assegna il ruolo. Nessuna password condivisa.</p><form data-employee="true"><div class="fields"><label>Nome<input name="name" maxlength="80" required></label><label>Email account ChatGPT<input type="email" name="email" required></label></div>${choiceTiles('role',[['waiter','Servizio'],['kitchen','Cucina / BAR'],['pass','Uscita'],['cashier','Cassa'],['admin','Admin']],'waiter','Ruolo')}<fieldset class="choice-field"><legend>Postazioni cucina (per il ruolo Cucina)</legend><div class="station-ticks">${Object.entries(stations).map(([id,label])=>`<label><input type="checkbox" name="staffStations" value="${id}"> ${label}</label>`).join('')}</div></fieldset><button>Crea account / aggiorna ruolo</button></form><div class="employee-list">${state.employees.map(e=>`<div class="bill-line"><span>${esc(e.name)} · ${esc(e.role)}<small>${esc(e.email)} · ${e.active?'Attivo':'Disabilitato'}</small></span>${e.id==='owner'?'<b>Proprietario</b>':btn(e.active?'Disabilita':'Riattiva','employee-toggle',`data-id="${e.id}"`)}</div>`).join('')}</div></section>`;}
function serviceSettingsMarkup(){const h=state.service.hours;return `<section class="panel"><h2>Orari & attivazione servizio</h2><p>Fuso orario: Europe/Rome. Il pranzo consente solo Pranzo; la cena consente Cena e À la carte.</p><form data-service="true"><div class="fields">${[['lunchStart','Pranzo dalle'],['lunchEnd','Pranzo fino alle'],['dinnerStart','Cena dalle'],['dinnerEnd','Cena fino alle']].map(([k,label])=>`<label>${label}<input type="text" name="${k}" value="${h[k]}" pattern="[0-9]{2}:[0-9]{2}" placeholder="HH:MM" required></label>`).join('')}</div><label class="check choice-square"><input name="enabled" type="checkbox" ${state.service.enabled?'checked':''}> Attiva ordini clienti</label><p>Verifica menu, prezzi e orari prima di attivare.</p><button>Salva orari e stato</button></form></section>`;}
function qrMarkup(){return `<section class="panel"><h2>Codici tavoli</h2><p>Apri o stampa il link del tavolo per i clienti. Il link resta utilizzabile soltanto quando il servizio apre il tavolo.</p><div class="qr-list">${Object.entries(state.tableMap).map(([n,p])=>`<div><b>T${n}</b> <a target="_blank" rel="noopener" href="/ordine/?table=${n}&key=${encodeURIComponent(p.token)}">Menu cliente</a><button type="button" data-action="show-qr" data-table="${n}">Codice QR</button></div>`).join('')}</div><div id="qr-display"></div></section>`;}
function recordsMarkup(){const today=BUSINESS_DATE;return `<section class="panel"><h2>Registro acquisti</h2><form data-purchase="true"><div class="fields"><label>Data (AAAA-MM-GG)<input name="date" value="${today}" pattern="[0-9]{4}-[0-9]{2}-[0-9]{2}" required></label><label>Fornitore<input name="supplier" maxlength="100" required></label><label>Articolo / descrizione<input name="description" maxlength="300" required></label><label>Quantità<input name="quantity" value="1" inputmode="decimal" required></label><label>Totale acquisto (€)<input name="amount" placeholder="0,00" inputmode="decimal" required></label></div><button>Registra acquisto</button></form>${state.purchases.map(r=>`<div class="bill-line"><span>${esc(r.date)} · ${esc(r.supplier)}<small>${esc(r.description)} · ${r.quantity}</small></span><b>${euros(r.amountCents)}</b></div>`).join('')}</section><section class="panel"><h2>Registro retribuzioni</h2><p>Registro interno di importi inseriti dall’amministratore. Non calcola contributi, imposte o buste paga.</p><form data-payroll="true">${choiceTiles('employee',state.employees.filter(e=>e.id!=='owner').map(e=>[e.id,e.name]),state.employees.find(e=>e.id!=='owner')?.id,'Dipendente')}<div class="fields"><label>Mese (AAAA-MM)<input name="period" value="${today.slice(0,7)}" pattern="[0-9]{4}-[0-9]{2}" required></label><label>Ore annotate<input name="hours" value="0" inputmode="decimal"></label><label>Importo registrato (€)<input name="amount" inputmode="decimal" required></label><label>Nota<input name="note" maxlength="300"></label></div><button ${state.employees.length<2?'disabled':''}>Registra retribuzione</button></form>${state.payroll.map(r=>`<div class="bill-line"><span>${esc(r.period)} · ${esc(r.name)}<small>${r.hours} ore · ${esc(r.note)}</small></span><b>${euros(r.amountCents)}</b></div>`).join('')}</section>`;}
function analyticsMarkup(){const r=REPORT;return `<section class="panel"><h2>Analisi vendite & tutti gli ordini</h2><form data-report="true"><div class="fields"><label>Dal (AAAA-MM-GG)<input name="from" value="${r?.from||BUSINESS_DATE}" required></label><label>Al (AAAA-MM-GG)<input name="to" value="${r?.to||BUSINESS_DATE}" required></label></div><button>Carica analisi</button></form>${!r?'<p>Carica il periodo per visualizzare ordini e incassi.</p>':`<div class="metric-grid"><div><small>Incassi registrati</small><b>${euros(r.revenueCents)}</b></div><div><small>Coperti chiusi</small><b>${r.covers}</b></div><div><small>Acquisti registrati</small><b>${euros(r.purchaseCents)}</b></div><div><small>Retribuzioni registrate</small><b>${euros(r.payrollCents)}</b></div></div><p>Gli incassi comprendono soltanto i conti chiusi. Non equivalgono a utile netto.</p>${Object.entries(r.daily).map(([date,total])=>`<div class="bill-line"><span>${date}</span><b>${euros(total)}</b></div>`).join('')}<h3>Ordini clienti</h3>${r.orders.map(o=>`<div class="report-order"><b>Tavolo ${o.table} · Giro ${o.round}</b><small>${new Date(o.time).toLocaleString('it-IT',{timeZone:'Europe/Rome'})}</small>${o.items.map(i=>`<div>${i.qty} × ${esc(i.name)} ${i.note?'· '+esc(i.note):''}</div>`).join('')}</div>`).join('')||'<p>Nessun ordine nel periodo.</p>'}`}</section>`;}
function importMenuMarkup(){return `<section class="panel"><h2>Aggiungi piatto</h2><form data-newdish="true"><div class="fields"><label>Numero / codice<input name="id" maxlength="80" required></label><label>Nome<input name="name" maxlength="100" required></label><label>Categoria<input name="category" value="Piatti caldi" maxlength="100" required></label><label>Prezzo piatto / extra (€)<input name="price" inputmode="decimal" placeholder="0,00"></label><label>Foto<input name="image" type="file" accept="image/jpeg,image/png,image/webp"></label></div>${choiceTiles('station',Object.entries(stations),'calda','Postazione iniziale')}${choiceTiles('chargeMode',[['included','Incluso AYCE'],['extra','Extra · bevande / dolci']],'included','Addebito')}<p>Puoi aggiungere altre postazioni e istruzioni dopo la creazione.</p><button>Aggiungi piatto</button></form></section><section class="panel"><h2>Importa configurazione precedente</h2><p>Importa menu e disposizione tavoli dal vecchio test. Ordini, conti simulati e account non vengono importati.</p><form data-import="true"><label>File JSON esportato dal vecchio sito<input type="file" name="configuration" accept="application/json,.json" required></label><label class="station-tick"><input type="checkbox" name="importPrices"> Importa anche i prezzi del file (da verificare)</label><button>Importa menu e mappa</button></form></section>`;}
function liveAdminTools(){return `${importMenuMarkup()}${serviceSettingsMarkup()}${staffMarkup()}${qrMarkup()}${analyticsMarkup()}${recordsMarkup()}`;}
async function liveForm(f,data){const before=cloneFront(state);try{if(f.dataset.settle){await settleForm(Number(f.dataset.settle),data.get('payment'));return true;}if(f.dataset.employee){const email=String(data.get('email')).trim().toLowerCase(),old=state.employees.find(e=>e.email===email);const role=data.get('role'),sts=data.getAll('staffStations');if(role==='kitchen'&&!sts.length)throw Error('Seleziona almeno una postazione cucina.');const record={id:old?.id||crypto.randomUUID(),name:String(data.get('name')).trim(),email,role,stations:role==='kitchen'?sts:[],active:true};if(old)Object.assign(old,record);else state.employees.push(record);}
 else if(f.dataset.newdish){const id=String(data.get('id')).trim();if(state.menu.some(d=>d.id===id))throw Error('Codice piatto già presente.');let image='/assets/placeholder.svg',file=data.get('image');if(file?.size){if(file.size>600000)throw Error('Foto inferiore a 600 KB.');image=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file)});}const station=data.get('station');state.menu.push({id,name:String(data.get('name')).trim(),category:String(data.get('category')).trim(),image,station,stations:[station],completionStation:station,stationInstructions:{[station]:''},limit:0,available:true,meal:'entrambi',priceCents:parseCents(data.get('price'),true),chargeMode:data.get('chargeMode')||'included'});}
 else if(f.dataset.import){if(Object.values(state.tables).some(t=>t.open))throw Error('Chiudi i tavoli prima di importare una configurazione.');const fdata=data.get('configuration');if(!fdata?.size||fdata.size>3000000)throw Error('File JSON non valido o troppo grande.');const config=JSON.parse(await fdata.text());if(!Array.isArray(config.menu)||!config.menu.length)throw Error('Il file non contiene un menu.');state.menu=config.menu.map(d=>({...d,meal:d.meal||'entrambi',limit:d.limit||0,available:d.available!==false,priceCents:Number.isInteger(d.priceCents)?d.priceCents:null}));if(Array.isArray(config.rooms)&&config.tableMap){state.rooms=config.rooms;state.tableMap={...state.tableMap,...config.tableMap};}if(data.has('importPrices')&&config.prices)state.prices=config.prices;}
 else if(f.dataset.service){state.service={enabled:data.has('enabled'),hours:Object.fromEntries(['lunchStart','lunchEnd','dinnerStart','dinnerEnd'].map(k=>[k,String(data.get(k)).trim()]))};}
 else if(f.dataset.purchase){state.purchases.unshift({id:crypto.randomUUID(),date:data.get('date'),supplier:data.get('supplier'),description:data.get('description'),quantity:Number(String(data.get('quantity')).replace(',','.')),amountCents:parseCents(data.get('amount'))});}
 else if(f.dataset.payroll){state.payroll.unshift({id:crypto.randomUUID(),employee:data.get('employee'),period:data.get('period'),hours:Number(String(data.get('hours')).replace(',','.')),amountCents:parseCents(data.get('amount')),note:data.get('note')});}
 else if(f.dataset.report){const u=apiURL('/api/report');u.searchParams.set('from',data.get('from'));u.searchParams.set('to',data.get('to'));const res=await fetch(u),d=await res.json();if(!res.ok)throw Error(d.error);REPORT=d;render();return true;}
 else return false;if(!await save())state=before;else notice='Dati salvati sul server.';render();return true;}catch(e){state=before;notice=e.message;const box=document.createElement('div');box.className='notice';box.textContent=notice;f.prepend(box);return true;}}
async function liveClick(a,b){if(a==='admin-tab'){adminTab=b.dataset.tab;render();return true;}if(a==='guest-meal'){await chooseGuestMeal(b.dataset.meal);return true;}if(a==='cash-table'){salaDialog={kind:'checkout',table:Number(b.dataset.table)};render();return true;}if(a==='employee-toggle'){const e=state.employees.find(e=>e.id===b.dataset.id);if(e&&e.id!=='owner'){const old=e.active;e.active=!old;if(!await save())e.active=old;render();}return true;}if(a==='show-qr'){const n=Number(b.dataset.table),p=state.tableMap[n],link=new URL('/ordine/?table='+n+'&key='+encodeURIComponent(p.token),location.origin).href;const box=document.querySelector('#qr-display');if(!window.renderQR){box.innerHTML=`<p>Tavolo ${n}</p><a href="${link}">${esc(link)}</a><p>Generatore QR non disponibile.</p>`;}else window.renderQR(box,link,n);return true;}return false;}

const url=(path='',p={})=>{const u=new URL(path,root);for(const [k,v] of Object.entries(p))u.searchParams.set(k==='tavolo'?'table':k,v);if(ROLE==='guest'){u.searchParams.set('table',table);u.searchParams.set('key',LIVE_PARAMS.get('key')||'');}return u.href;};
const nav=(path,label)=>`<a href="${url(path)}">${label}</a>`;
function shell(body){document.body.innerHTML=`<main><div role="status" class="connection-status notice" ${online?'hidden':''}>Connessione assente · riprova prima di inviare</div>${notice?`<div role="status" class="notice">${esc(notice)}</div>`:''}${body}</main><footer>GIN SUSHI · <a href="/">Portali</a>${ME?' · <a target="_top" href="/signout-with-chatgpt?return_to=/">Esci</a>':''}</footer>${quantityMarkup()}${view==='cassa'?cashDialogMarkup():serviceTableDialog()}`}

const btn=(text,action,extra='')=>`<button type="button" data-action="${action}" ${extra}>${text}</button>`;
const selected=()=>state.menu.filter(d=>cart[d.id]>0);
const active=()=>state.tables[table]?.open;
function countUsed(id){const t=state.tables[table];return state.orders.filter(o=>o.table===table&&o.session===t?.session).flatMap(o=>o.items).filter(i=>i.dish===id).reduce((a,i)=>a+i.qty,0)}
function eligible(){const t=state.tables[table];return state.menu.filter(d=>d.available&&(d.meal==='entrambi'||d.meal===t?.meal||(t?.meal==='carta'&&d.meal==='cena')||!t?.meal))}
function menuPreview(){const menu=state.menu.filter(d=>d.available&&(cat==='Tutti'||d.category===cat)&&(`${d.name} ${d.id}`.toLowerCase().includes(query.toLowerCase()))),cats=['Tutti',...new Set(state.menu.filter(d=>d.available).map(d=>d.category))];shell(`<div class="title"><div><small>GIN SUSHI</small><h1>Menu cliente</h1></div></div><p class="notice">Anteprima del menu. Per ordinare, scansiona il QR del tuo tavolo dopo l’apertura da parte del personale.</p><input id="search" placeholder="Cerca nome o numero…" aria-label="Cerca piatto" value="${esc(query)}"><div class="menu-layout"><aside>${cats.map(c=>`<button class="${cat===c?'active':''}" data-cat="${esc(c)}">${esc(c)}</button>`).join('')}</aside><section class="cards">${menu.map(d=>`<article class="dish"><img src="${esc(d.image)}" alt="${esc(d.name)}"><div class="info"><small>N. ${esc(d.id)}</small><h3>${esc(d.name)}</h3></div></article>`).join('')||'<div class="empty">Nessun piatto trovato</div>'}</section></div>`);}
function client(){if(ROLE==='visitor')return menuPreview();const t=state.tables[table],menu=eligible(),cats=['Tutti',...new Set(menu.map(d=>d.category))],sum=Object.values(cart).reduce((a,b)=>a+b,0);shell(`<div class="title"><div><small>MENU ALL YOU CAN EAT</small><h1>Tavolo ${String(table).padStart(2,'0')}</h1><p>${active()?`${t.adults??t.people} adulti · ${t.children||0} bambini · ${t.meal==='cena'?'Cena':t.meal==='carta'?'À la carte':t.meal==='pranzo'?'Pranzo':'Menu da scegliere'} · Tavolo aperto`:'Tavolo chiuso · Chiedi al personale di aprirlo'}</p></div><a class="pill" href="${url('storico/',{tavolo:table})}">I miei ordini →</a></div>${active()&&!t.meal?chooseMealMarkup():!active()?`<div class="empty"><h2>Benvenuti da GIN SUSHI</h2><p>Il personale apre il tavolo prima dell’ordine.</p></div>`:`<input id="search" placeholder="Cerca nome o numero…" aria-label="Cerca piatto" value="${esc(query)}"><div class="menu-layout"><aside>${cats.map(c=>`<button class="${cat===c?'active':''}" data-cat="${esc(c)}">${esc(c)}</button>`).join('')}</aside><section class="cards">${menu.filter(d=>(cat==='Tutti'||d.category===cat)&&(`${d.name} ${d.id}`.toLowerCase().includes(query.toLowerCase()))).map(d=>`<article class="dish"><img src="${d.image}" alt="${esc(d.name)}"><div class="info"><small>N. ${esc(d.id)}</small><h3>${esc(d.name)}</h3><span class="muted">${(t?.meal==='carta'||d.chargeMode==='extra')?(Number.isInteger(d.priceCents)?euros(d.priceCents):'Non ordinabile · prezzo mancante')+' · ':''}${d.limit?`Limite tavolo: ${d.limit} · Ordinati: ${countUsed(d.id)}`:'Senza limite'}</span><div class="qty">${btn('−','minus',`data-id="${d.id}" aria-label="Riduci ${esc(d.name)}"`)}<b>${cart[d.id]||0}</b>${btn('+','plus',`data-id="${d.id}" aria-label="Aggiungi ${esc(d.name)}" ${(t?.meal==='carta'||d.chargeMode==='extra')&&!Number.isInteger(d.priceCents)?'disabled':''}`)}</div></div></article>`).join('')||'<div class="empty">Nessun piatto trovato</div>'}</section></div><div class="cartbar"><b>${sum} porzioni selezionate</b>${btn('Carrello →','cart',sum?'':'disabled')}</div>`}`)}
function cartPage(){shell(`<h1>Il tuo carrello</h1><p>Tavolo ${table} · Giro ${state.tables[table]?.nextRound||1}</p><section class="panel">${selected().map(d=>`<div class="cartrow"><div><b>${esc(d.name)}</b><p>${cart[d.id]} porzioni</p><input data-note="${d.id}" placeholder="Richieste per la cucina" aria-label="Note ${esc(d.name)}" value="${esc(notes[d.id]||'')}"></div><div class="qty">${btn('−','cartminus',`data-id="${d.id}"`)}${btn('+','cartplus',`data-id="${d.id}"`)}</div></div>`).join('')||'<p>Il carrello è vuoto.</p>'}<div class="actions">${btn('← Continua','back')}${btn('Invia ordine','submit',selected().length?'':'disabled')}</div></section>`)}
function history(){const t=state.tables[table],orders=state.orders.filter(o=>o.table===table&&o.session===t?.session);shell(`<div class="title"><h1>Ordini · Tavolo ${table}</h1><a class="pill" href="${url('',{tavolo:table})}">Torna al menu</a></div>${orders.map(o=>`<section class="panel"><small>${esc(o.id)} · ${new Date(o.time).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})} · Giro ${o.round}</small>${o.items.map(i=>`<div class="item"><span>${i.qty} × ${esc(i.name)}${i.note?`<small>${esc(i.note)}</small>`:''}</span><span class="status ${i.status}">${i.qty-i.readyQty} da preparare · ${i.readyQty-i.servedQty} pronti · ${i.servedQty} serviti</span></div>`).join('')}</section>`).join('')||'<div class="empty">Nessun ordine in questa sessione.</div>'}`)}
function ensureSala(){
 if(!state.rooms?.length)state.rooms=[{id:'sala1',name:'Sala 1'},{id:'sala2',name:'Sala 2'}];
 if(!state.tableMap){state.tableMap={};for(let n=1;n<=20;n++)state.tableMap[n]={room:n<=10?'sala1':'sala2',x:12+((n-1)%5)*18,y:22+(Math.floor(((n-1)%10)/5))*45};}
 for(const n of Object.keys(state.tables)){if(!state.tableMap[n])state.tableMap[n]={room:state.rooms[0].id,x:50,y:50};const t=state.tables[n];if(!Number.isInteger(t.adults))t.adults=t.people||0;if(!Number.isInteger(t.children))t.children=0;}
 if(!state.prices)state.prices={pranzo:{adult:1490,child:890},cena:{adult:null,child:null},coverAdult:200,coverChild:200};
 if(!state.receipts)state.receipts=[];
}
const euros=c=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(c/100);
function currentRates(meal){const p=state.prices,m=meal==='carta'?{adult:0,child:0,kind:'carta'}:p[meal];return m?{adult:m.adult,child:m.child,coverAdult:p.coverAdult,coverChild:p.coverChild}:null;}
function billFor(adults,children,rates){if(!rates||!Number.isInteger(rates.adult)||!Number.isInteger(rates.child)||!Number.isInteger(rates.coverAdult)||!Number.isInteger(rates.coverChild))return null;const lines=[{name:'Menu adulti',qty:adults,unit:rates.adult},{name:'Menu bambini',qty:children,unit:rates.child},{name:'Coperto adulti',qty:adults,unit:rates.coverAdult},{name:'Coperto bambini',qty:children,unit:rates.coverChild}];return {adults,children,lines,total:lines.reduce((n,l)=>n+l.qty*l.unit,0)};}
function billMarkup(bill){return bill?`<div class="bill-lines">${bill.lines.filter(l=>l.qty).map(l=>`<div class="bill-line"><span>${l.name}<small>${l.qty} × ${euros(l.unit)}</small></span><b>${euros(l.qty*l.unit)}</b></div>`).join('')}<div class="bill-total"><span>Totale menu + coperto</span><strong>${euros(bill.total)}</strong></div></div><small>Menu, coperto ed extra ordinati. Conto di servizio, non documento fiscale.</small>`:'<div class="notice">Prezzi di questo menu da configurare in Admin prima di aprire il tavolo.</div>';}
function pendingTable(n){const t=state.tables[n];return state.orders.filter(o=>o.table===n&&o.session===t?.session).flatMap(o=>o.items).reduce((sum,i)=>sum+i.qty-i.servedQty,0);}
function updateBillPreview(form){if(!form)return;const box=form.querySelector('.bill-preview');if(!box)return;const f=new FormData(form),n=Number(form.dataset.attendance||form.dataset.open),t=state.tables[n],rates=t?.open?(t.rates||currentRates(t.meal)):currentRates(f.get('meal'));box.innerHTML=billMarkup(billFor(Number(f.get('adults')),Number(f.get('children')),rates));}
function floorIcon(){return '<svg viewBox="0 0 64 46" aria-hidden="true"><path d="M8 8h48l6 9v7H2v-7zM6 24h7v20H6zm45 0h7v20h-7zM17 24h30v5H17z" fill="currentColor"/></svg>';}
function floorPlan(editable=false){ensureSala();if(!state.rooms.some(r=>r.id===activeRoom))activeRoom=state.rooms[0].id;const room=state.rooms.find(r=>r.id===activeRoom),entries=Object.entries(state.tableMap).filter(([n,p])=>p.room===activeRoom);return `<div class="floor-toolbar"><div class="room-tabs">${state.rooms.map(r=>btn(esc(r.name),'room',`data-room="${r.id}" class="${activeRoom===r.id?'active':''}"`)).join('')}</div>${editable?`<div class="actions">${btn('+ Area','addroom')}${btn('+ Tavolo','addtable')}${btn(movingTables?'Fine spostamento ✓':'Sposta tavoli','moving',`aria-pressed="${movingTables}"`)}</div>`:''}</div><p class="floor-help">${movingTables?'Trascina i tavoli per posizionarli. Le posizioni vengono salvate automaticamente. Tocca senza trascinare per cambiare area.':(editable?'Tocca un tavolo aperto per il conto.':'Tocca un tavolo per aprirlo o modificare le persone.')}</p><div class="floor-legend"><span><i></i>Libero</span><span><i class="occupied"></i>Aperto</span></div><section class="floor-map ${movingTables?'is-moving':''}" aria-label="Mappa ${esc(room.name)}">${entries.map(([n,p])=>`<button type="button" class="floor-table ${state.tables[n]?.open?'occupied':''}" data-action="table" data-table="${n}" style="left:${p.x}%;top:${p.y}%" aria-label="Tavolo ${n}, ${state.tables[n]?.open?'aperto':'libero'}">${floorIcon()}<b>${esc(n)}</b></button>`).join('')}${!entries.length?'<p class="empty-room">Nessun tavolo in questa area.</p>':''}</section>`;}
function sala(){shell(`<div class="title"><div><small>SERVIZIO</small><h1>Gestione tavoli</h1></div><span class="pill">${Object.values(state.tables).filter(t=>t.open).length} tavoli aperti</span></div>${floorPlan()}`);}

function legacySalaDialogMarkup(){if(!salaDialog)return '';ensureSala();const d=salaDialog;let body='';if(d.kind==='room')body=`<h2>Nuova area</h2><form data-newroom="true"><label>Nome area<input name="roomName" value="Sala ${state.rooms.length+1}" maxlength="30" required></label><div class="actions">${btn('Annulla','sala-dismiss')}<button>Crea area</button></div></form>`;
 if(d.kind==='newtable'){const next=Math.max(0,...Object.keys(state.tableMap).map(Number))+1;body=`<h2>Nuovo tavolo</h2><form data-newtable="true">${numberStepper('tableNumber',next,1,999,'Numero tavolo')}${choiceTiles('room',state.rooms.map(r=>[r.id,r.name]),activeRoom,'Area')}<div class="actions">${btn('Annulla','sala-dismiss')}<button>Aggiungi tavolo</button></div></form>`;}
 if(['table','checkout','move'].includes(d.kind)){const n=d.table,t=state.tables[n],p=state.tableMap[n];body=`<div class="title"><h2>Tavolo ${n}</h2>${btn('✕','sala-dismiss','aria-label="Chiudi pannello"')}</div>`;
 if(d.kind==='move')body+=`<form data-movetable="${n}">${choiceTiles('room',state.rooms.map(r=>[r.id,r.name]),p.room,'Sposta in area')}<button>Salva area</button></form>`;
 else if(d.kind==='checkout'){const bill=billFor(t.adults,t.children,t.rates||currentRates(t.meal)),pending=pendingTable(n);body+=`<p>${t.meal==='cena'?'Cena':t.meal==='carta'?'À la carte':t.meal==='pranzo'?'Pranzo':'Menu da scegliere'} · ${t.adults} adulti · ${t.children} bambini</p>${billMarkup(bill)}${pending?`<div class="notice">${pending} porzioni ancora da servire. Completa il servizio prima di chiudere.</div>`:''}<div class="actions">${btn('← Torna','table',`data-table="${n}"`)}${btn('Conferma conto e chiudi tavolo demo','settle',`data-table="${n}" ${!bill||pending?'disabled':''}`)}</div>`;}
 else {const adults=t?.open?t.adults:2,children=t?.open?t.children:0,meal=t?.open?t.meal:'pranzo',rates=t?.open?(t.rates||currentRates(meal)):currentRates(meal);body+=`${t?.open?`<p>Tavolo aperto · ${meal==='cena'?'Cena':'Pranzo'}</p><a class="pill" href="${url('',{tavolo:n})}">Menu cliente ↗</a>`:''}<form ${t?.open?`data-attendance="${n}"`:`data-open="${n}"`}>${numberStepper('adults',adults,0,99,'Adulti')}${numberStepper('children',children,0,99,'Bambini')}${t?.open?'':choiceTiles('meal',[['pranzo','Pranzo'],['cena','Cena']],meal,'Menu')}<div class="bill-preview">${billMarkup(billFor(adults,children,rates))}</div><div class="actions"><button>${t?.open?'Salva persone':'Apri tavolo'}</button>${t?.open?btn('Calcola conto →','checkout',`data-table="${n}"`):''}</div></form>`;}}
 return `<div class="quantity-overlay"><section class="panel sala-dialog" role="dialog" aria-modal="true" aria-label="Gestione tavolo">${body}</section></div>`;}
function pricingMarkup(){ensureSala();const value=c=>Number.isInteger(c)?(c/100).toFixed(2):'';const priceInput=(name,label,c,required=true)=>`<label>${label}<input type="text" name="${name}" inputmode="decimal" placeholder="0,00" value="${value(c)}" ${required?'required':''} pattern="[0-9]+([.,][0-9]{1,2})?"></label>`;return `<section class="panel pricing-panel"><h2>Menu & coperto · Prezzi per persona</h2><p>Inserisci i prezzi reali del ristorante prima di attivare gli ordini. I prezzi vengono fissati all’apertura del tavolo.</p><form data-prices="true"><div class="fields">${priceInput('pranzoAdult','Pranzo · adulto (€)',state.prices.pranzo.adult)}${priceInput('pranzoChild','Pranzo · bambino (€)',state.prices.pranzo.child)}${priceInput('cenaAdult','Cena · adulto (€)',state.prices.cena.adult,false)}${priceInput('cenaChild','Cena · bambino (€)',state.prices.cena.child,false)}${priceInput('coverAdult','Coperto · adulto (€)',state.prices.coverAdult)}${priceInput('coverChild','Coperto · bambino (€)',state.prices.coverChild)}</div><button>Salva prezzi</button></form></section>`;}
function parseCents(v,optional=false){const x=String(v??'').trim();if(!x&&optional)return null;if(!/^\d+([.,]\d{1,2})?$/.test(x))throw Error('Prezzo non valido');const [a,b='']=x.replace(',','.').split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n)||n<0||n>1000000)throw Error('Prezzo non valido');return n;}
async function salaClick(a,b){if(!['sala','cassa','admin'].includes(view))return false;ensureSala();if(suppressTableClick&&a==='table'){suppressTableClick=false;return true;}if(a==='room'){activeRoom=b.dataset.room;salaDialog=null;render();return true;}if(['moving','addroom','addtable','move-table'].includes(a)&&view!=='cassa'&&view!=='admin')return true;if(a==='moving'){movingTables=!movingTables;render();return true;}if(a==='addroom'){salaDialog={kind:'room'};render();return true;}if(a==='addtable'){salaDialog={kind:'newtable'};render();return true;}if(a==='table'){const n=Number(b.dataset.table);if(!state.tableMap[n])return true;if(view==='cassa'&&!movingTables&&!state.tables[n]?.open)return true;salaDialog={kind:movingTables?'move':view==='cassa'?'checkout':'table',table:n};render();return true;}if(a==='sala-dismiss'){salaDialog=null;render();return true;}if(a==='checkout'||a==='move-table'){salaDialog={kind:a==='checkout'?'checkout':'move',table:Number(b.dataset.table)};render();return true;}if(a==='settle'){const n=Number(b.dataset.table),t=state.tables[n];if(!t?.open)return true;const bill=billFor(t.adults,t.children,t.rates||currentRates(t.meal));if(!bill||pendingTable(n)){notice='Controlla i prezzi e completa il servizio prima di chiudere.';render();return true;}const before=JSON.stringify(state);state.receipts.push({...bill,table:n,session:t.session,meal:t.meal,time:Date.now()});state.receipts=state.receipts.slice(-50);t.open=false;t.lastBill=bill;if(!await save())state=JSON.parse(before);else notice='Tavolo '+n+' chiuso · '+euros(bill.total)+' menu e coperto.';salaDialog=null;render();return true;}return false;}
async function salaSubmit(f,data){if(!['sala','cassa','admin'].includes(view)||!['newroom','newtable','movetable','prices','open','attendance'].some(k=>f.dataset[k]))return false;ensureSala();let handled=true;const before=JSON.stringify(state);try{
 if(f.dataset.newroom){const name=String(data.get('roomName')||'').trim();if(!name)throw Error('Inserisci il nome dell’area.');const id='sala'+Date.now();state.rooms.push({id,name});activeRoom=id;salaDialog=null;}
 else if(f.dataset.newtable){const n=Number(data.get('tableNumber')),room=data.get('room');if(!Number.isInteger(n)||n<1||n>999||state.tableMap[n]||!state.rooms.some(r=>r.id===room))throw Error('Numero già usato o area non valida.');const positions=Object.values(state.tableMap).filter(p=>p.room===room);const k=positions.length;state.tableMap[n]={room,x:12+(k%5)*18,y:Math.min(85,22+Math.floor(k/5)*30)};activeRoom=room;salaDialog=null;}
 else if(f.dataset.movetable){const n=Number(f.dataset.movetable),room=data.get('room');if(!state.tableMap[n]||!state.rooms.some(r=>r.id===room))throw Error('Area non valida.');state.tableMap[n]={room,x:50,y:50};activeRoom=room;salaDialog=null;}
 else if(f.dataset.prices){const p={pranzo:{adult:parseCents(data.get('pranzoAdult')),child:parseCents(data.get('pranzoChild'))},cena:{adult:parseCents(data.get('cenaAdult'),true),child:parseCents(data.get('cenaChild'),true)},coverAdult:parseCents(data.get('coverAdult')),coverChild:parseCents(data.get('coverChild'))};if((p.cena.adult===null)!==(p.cena.child===null))throw Error('Inserisci entrambi i prezzi cena.');state.prices=p;notice='Prezzi salvati. Valgono per i nuovi tavoli.';}
 else if(f.dataset.open||f.dataset.attendance){const n=Number(f.dataset.open||f.dataset.attendance),adults=Number(data.get('adults')),children=Number(data.get('children'));if(!Number.isInteger(adults)||!Number.isInteger(children)||adults<0||children<0||adults>99||children>99||adults+children<1)throw Error('Inserisci almeno una persona.');const old=state.tables[n];if(f.dataset.open&&old?.open)throw Error('Tavolo già aperto.');if(f.dataset.attendance&&!old?.open)throw Error('Il tavolo non è aperto.');if(f.dataset.open)state.tables[n]={open:true,adults,children,people:adults+children,meal:null,rates:null,session:crypto.randomUUID(),nextRound:1,waiterName:ME.name};else Object.assign(old,{adults,children,people:adults+children});notice='Tavolo '+n+' · '+adults+' adulti, '+children+' bambini.';salaDialog={kind:'table',table:n};}
 else handled=false;
 if(handled){if(!await save())state=JSON.parse(before);render();}
 }catch(e){state=JSON.parse(before);notice=e.message;const box=document.createElement('div');box.className='notice';box.setAttribute('role','status');box.textContent=notice;f.prepend(box);}return handled;}
function installFloorDrag(){let drag=null;document.addEventListener('pointerdown',e=>{const el=e.target.closest('.floor-table');if(!['cassa','admin'].includes(view)||!movingTables||!el||e.button!==0)return;suppressTableClick=false;const board=el.closest('.floor-map');drag={el,board,id:Number(el.dataset.table),pointer:e.pointerId,startX:e.clientX,startY:e.clientY,x:state.tableMap[el.dataset.table].x,y:state.tableMap[el.dataset.table].y,moved:false};el.setPointerCapture(e.pointerId);});document.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;const r=drag.board.getBoundingClientRect(),dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;if(!drag.moved)return;const marginX=45/r.width*100,marginY=50/r.height*100;drag.x=Math.max(marginX,Math.min(100-marginX,state.tableMap[drag.id].x+dx/r.width*100));drag.y=Math.max(marginY,Math.min(100-marginY,state.tableMap[drag.id].y+dy/r.height*100));drag.el.style.left=drag.x+'%';drag.el.style.top=drag.y+'%';});const end=async e=>{if(!drag||drag.pointer!==e.pointerId)return;const d=drag;drag=null;if(d.moved){suppressTableClick=true;const old={...state.tableMap[d.id]};Object.assign(state.tableMap[d.id],{x:d.x,y:d.y});if(!await save())state.tableMap[d.id]=old;}};document.addEventListener('pointerup',end);document.addEventListener('pointercancel',e=>{if(!drag)return;drag.el.style.left=state.tableMap[drag.id].x+'%';drag.el.style.top=state.tableMap[drag.id].y+'%';drag=null;});}

function kitchen(){if(!stations[station])station='calda';const groups=groupItems('complete');shell(`<div class="title"><div><small>POSTAZIONE</small><h1>${stations[station]}</h1></div><span class="pill">${groups.reduce((a,g)=>a+g.total,0)} porzioni</span></div><div class="tabs">${Object.entries(stations).filter(([id])=>ROLE!=='kitchen'||ME.stations.includes(id)).map(([id,label])=>`<a class="${station===id?'active':''}" href="${url('cucina/',{station:id})}">${label}</a>`).join('')}</div><section class="kitchengrid">${groups.map(g=>`<article class="panel kitchen-photo-card">${g.image?`<img class="kitchen-backdrop" src="${esc(g.image)}" alt="" aria-hidden="true">`:""}<div class="dish-heading"><h2>${esc(g.name)}</h2><strong>×${g.total}</strong></div>${g.instructions?`<p class="composition">${esc(g.instructions)}</p>`:''}${g.note?`<p class="special-note">${esc(g.note)}</p>`:''}<div class="tiles">${[...g.rows.values()].map(row=>tableTile(row,g,'complete')).join('')}</div></article>`).join('')||'<div class="empty"><h2>Nessun piatto in attesa</h2></div>'}</section>`)}
function uscita(){const ready=groupItems('serve'),served=groupItems('undo');const section=(groups,kind)=>`<section class="kitchengrid">${groups.map(g=>`<article class="panel"><div class="service-heading">${g.image?`<img class="service-photo" src="${esc(g.image)}" alt="${esc(g.name)}">`:''}<div><small>N. ${esc(g.dish)}</small><h2>${esc(g.name)}</h2></div><strong>×${g.total}</strong></div>${g.note?`<p class="special-note">${esc(g.note)}</p>`:''}<div class="tiles">${[...g.rows.values()].map(row=>tableTile(row,g,kind)).join('')}</div></article>`).join('')||'<div class="empty">Nessun piatto.</div>'}</section>`;shell(`<div class="title"><div><small>SERVIZIO</small><h1>Piatti pronti</h1></div><span class="pill">${ready.reduce((a,g)=>a+g.total,0)} porzioni</span></div>${section(ready,'serve')}<h2 class="section-title">Già serviti · Annulla servizio</h2>${section(served,'undo')}`)}
function menuEditorMarkup(){return `<section class="adminlist">${state.menu.map(d=>`<form class="panel editor" data-edit="${d.id}"><div><small>N. ${d.id}</small><h2>${esc(d.name)}</h2><img class="thumb" src="${d.image}" alt="${esc(d.name)}"></div><div class="fields"><label>Nome<input name="name" required maxlength="100" value="${esc(d.name)}"></label>${stationEditor(d)}${choiceTiles('meal',[['entrambi','Pranzo + Cena'],['pranzo','Pranzo'],['cena','Cena + À la carte'],['carta','Solo À la carte']],d.meal,'Menu')}${choiceTiles('chargeMode',[['included','Incluso AYCE'],['extra','Extra · bevande / dolci']],d.chargeMode||'included','Addebito')}${numberStepper('limit',d.limit||0,0,999,'Limite per tavolo')}<label>Prezzo piatto / extra (€)<input name="priceCents" type="text" inputmode="decimal" value="${Number.isInteger(d.priceCents)?(d.priceCents/100).toFixed(2):''}" placeholder="Da impostare"></label><label class="wide">Sostituisci foto<input name="image" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="check choice-square"><input name="available" type="checkbox" ${d.available?'checked':''}> Disponibile</label><button>Salva piatto</button></div></form>`).join('')}</section>`;}
function admin(){const tabs=[['overview','Panoramica'],['menu','Menu'],['prices','Prezzi'],['service','Orari'],['employees','Dipendenti'],['analytics','Vendite & ordini'],['purchases','Acquisti'],['payroll','Retribuzioni'],['qr','Codici QR']];const markers=recordsMarkup().split('<section class="panel"><h2>Registro retribuzioni');const records=adminTab==='purchases'?markers[0]:'<section class="panel"><h2>Registro retribuzioni'+markers[1];const summary=`<section class="panel"><h2>Preparazione al servizio</h2><div class="metric-grid"><div><small>Servizio clienti</small><b>${state.service.enabled?'Attivo':'Da attivare'}</b></div><div><small>Piatti registrati</small><b>${state.menu.length}</b></div><div><small>Dipendenti</small><b>${state.employees.filter(e=>e.id!=='owner'&&e.active).length}</b></div><div><small>Tavoli</small><b>${Object.keys(state.tableMap).length}</b></div></div><p>1. Verifica o importa il menu completo e imposta i prezzi alla carta.</p><p>2. Imposta prezzi menu/coperto e gli orari reali.</p><p>3. Abilita le email dei dipendenti e assegna i ruoli.</p><p>4. Stampa i codici tavolo, fai una prova tra i dispositivi e attiva gli ordini.</p><p>Le impostazioni demo del vecchio sito si possono esportare e importare nella sezione Menu.</p></section>`;const content=adminTab==='overview'?summary:adminTab==='menu'?importMenuMarkup()+menuEditorMarkup():adminTab==='prices'?pricingMarkup():adminTab==='service'?serviceSettingsMarkup():adminTab==='employees'?staffMarkup():adminTab==='analytics'?analyticsMarkup():adminTab==='qr'?qrMarkup():records;shell(`<div class="title"><div><small>AMMINISTRAZIONE</small><h1>Gestione ristorante</h1></div><b>${esc(ME.name)}</b></div><div class="admin-tabs">${tabs.map(([id,label])=>btn(label,'admin-tab',`data-tab="${id}" class="${adminTab===id?'active':''}"`)).join('')}</div>${content}`);}
function guide(){shell(`<h1>Portali del ristorante</h1><section class="panel"><p>Servizio: apre il tavolo e registra adulti e bambini. Il cliente sceglie il menu dal proprio codice QR.</p><p>Cucina: mostra le istruzioni di ciascuna postazione. Solo il responsabile conferma le porzioni pronte.</p><p>Uscita: registra il servizio e consente di annullarlo. Cassa: calcola il conto e registra un pagamento ricevuto.</p><p>Il server salva gli ordini condivisi. Se manca la connessione, l’operazione non viene confermata: riconnetti e riprova.</p></section>`)}
function render(){document.title='GIN SUSHI · '+({cliente:'Menu',cart:'Carrello',sala:'Sala',cucina:stations[station],uscita:'Uscita',admin:'Admin',cassa:'Cassa',storico:'Ordini',guida:'Guida'})[view];({cliente:client,cart:cartPage,sala,cassa,cucina:kitchen,uscita,admin,storico:history,guida:guide}[view]||client)()}
function change(id,n){const d=state.menu.find(d=>d.id===id);if(!d)return;if(n>0&&d.limit&&countUsed(id)+(cart[id]||0)+1>d.limit){notice='Limite del tavolo raggiunto per '+d.name;render();return}cart[id]=Math.max(0,(cart[id]||0)+n);notice='';render()}
async function submit(){if(uncertainWrite){notice='Verifico l’invio precedente. Non inviare un secondo ordine.';await recoverWrite();return;}if(!active()){notice='Il tavolo è stato chiuso.';view='cliente';render();return}const ds=selected();if(!ds.length)return;for(const d of ds){if(!eligible().some(x=>x.id===d.id)||(d.limit&&countUsed(d.id)+cart[d.id]>d.limit)){notice='Disponibilità o limite cambiato. Controlla il carrello.';render();return}}const time=Date.now(),session=state.tables[table].session;const items=ds.map((d,n)=>({id:time+'-'+n,dish:d.id,name:d.name,qty:cart[d.id],note:(notes[d.id]||'').trim(),station:assigned(d)[0],stations:assigned(d),completionStation:owner(d),stationInstructions:Object.fromEntries(assigned(d).map(st=>[st,instruction(d,st)])),instructions:d.instructions,readyQty:0,servedQty:0,status:'new'}));const order={id:'G'+crypto.randomUUID(),table,session,round:state.tables[table].nextRound||1,time,items};state.orders.push(order);state.tables[table].nextRound=order.round+1;if(!await save()){state.orders.pop();state.tables[table].nextRound=order.round;render();return}cart={};notes={};view='storico';notice='Ordine ricevuto dal ristorante.';render()}
document.addEventListener('click',async e=>{const c=e.target.closest('[data-cat]');if(c){cat=c.dataset.cat;render();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(await liveClick(a,b))return;if(await salaClick(a,b))return;if(a==='step'){const control=b.closest('.number-stepper'),input=control.querySelector('input'),output=control.querySelector('output');input.value=Math.max(Number(control.dataset.min),Math.min(Number(control.dataset.max),Number(input.value)+Number(b.dataset.delta)));output.textContent=input.name==='limit'&&Number(input.value)===0?'∞':input.value;updateBillPreview(b.closest('form'));return}if(['plus','minus','cartplus','cartminus'].includes(a))change(id,a.includes('minus')?-1:1);if(a==='cart'){view='cart';render()}if(a==='back'){view='cliente';render()}if(a==='submit')await submit();if(a==='quantity'){const refs=JSON.parse(b.dataset.refs);const kind=b.dataset.kind;if(kind==='complete'&&refs.some(ref=>{const {i}=findItem(ref);return !i||owner(i)!==station}))return;quantityDialog={refs,kind,name:b.dataset.name,table:b.dataset.table};render()}if(a==='dismiss'){quantityDialog=null;render()}if(a==='close'){salaDialog={kind:'checkout',table:Number(b.dataset.table)};render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}if(e.target.dataset.note)notes[e.target.dataset.note]=e.target.value});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,data=new FormData(f);if(await liveForm(f,data))return;if(await salaSubmit(f,data))return;if(f.dataset.quantity){if(!quantityDialog)return;const d=quantityDialog,n=Number(data.get('quantity')),items=d.refs.map(findItem);const available=items.reduce((a,{i})=>a+(i?amount(i,d.kind):0),0);if(!Number.isInteger(n)||n<1||n>available||(d.kind==='complete'&&items.some(({i})=>!i||owner(i)!==station))){notice='Quantità non valida o postazione non autorizzata.';render();return}const before=JSON.stringify(state);let left=n;for(const {i} of items){if(!i||!left)continue;const q=Math.min(left,amount(i,d.kind));if(d.kind==='complete')i.readyQty+=q;else if(d.kind==='serve')i.servedQty+=q;else i.servedQty-=q;syncStatus(i);left-=q}if(!await save())state=JSON.parse(before);else notice=d.kind==='complete'?n+' porzioni pronte.':d.kind==='serve'?n+' porzioni servite.':n+' porzioni ripristinate tra i piatti pronti.';quantityDialog=null;render();return}if(f.dataset.edit){const chosen=data.getAll('stations').filter(s=>stations[s]);if(!chosen.length||!chosen.includes(data.get('completionStation'))){notice='Seleziona almeno una postazione e un solo responsabile tra quelle selezionate.';const box=document.createElement('div');box.className='notice';box.setAttribute('role','status');box.textContent=notice;f.prepend(box);return}const d=state.menu.find(d=>d.id===f.dataset.edit),file=data.get('image');let image=d.image;if(file?.size){if(file.size>600000){notice='Usa una foto inferiore a 600 KB.';render();return}image=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file)})}const old={...d};Object.assign(d,{name:String(data.get('name')).trim(),station:chosen[0],stations:chosen,completionStation:data.get('completionStation'),stationInstructions:Object.fromEntries(Object.keys(stations).map(st=>[st,String(data.get('instructions_'+st)||'').trim()])),meal:data.get('meal'),limit:Number(data.get('limit'))||0,priceCents:parseCents(data.get('priceCents'),true),chargeMode:data.get('chargeMode')||'included',available:data.has('available'),image});if(await save())notice='Piatto salvato: '+d.name;else Object.assign(d,old);render()}});
if(!await initializeLive())return;
if(ROLE!=='guest')ensureSala();
installFloorDrag();
document.addEventListener('change',e=>{if(e.target.name==='stations'){const form=e.target.closest('form');for(const cb of form.querySelectorAll('input[name="stations"]')){const detail=form.querySelector('[data-detail="'+cb.value+'"]');detail.hidden=!cb.checked;const radio=detail.querySelector('input[type="radio"]');radio.disabled=!cb.checked;if(!cb.checked)radio.checked=false;}if(!form.querySelector('input[name="completionStation"]:checked')){const first=form.querySelector('input[name="stations"]:checked');if(first)form.querySelector('input[name="completionStation"][value="'+first.value+'"]').checked=true;}}});
setInterval(()=>syncLive(),2000);
render();
})();
